1	import { useEffect, useState } from "react";
2	import { useLocation } from "wouter";
3	import { useQueryClient } from "@tanstack/react-query";
4	import { Layout } from "@/components/layout";
5	import {
6	  CheckCircle2, Calendar, Clock, ArrowRight, Loader2, XCircle,
7	  Users, Copy, Check, Globe, Share2, ExternalLink, CreditCard, UserPlus,
8	  ChevronDown, Download, MessageCircle,
9	} from "lucide-react";
10	import { Button } from "@/components/ui/button";
11	import {
12	  DropdownMenu,
13	  DropdownMenuContent,
14	  DropdownMenuItem,
15	  DropdownMenuTrigger,
16	} from "@/components/ui/dropdown-menu";
17	import { format } from "date-fns";
18	import { useSafeAuth } from "@/lib/safeAuth";
19	import { SignUp } from "@clerk/react";
20	import { openChat } from "@/components/chat-bubble";
21	
22	const clerkPubKey = import.meta.env.VITE_CLERK_PUBLISHABLE_KEY as string | undefined;
23	
24	const BASE = import.meta.env.BASE_URL.replace(/\/$/, "");
25	const API = `${BASE}/api`;
26	
27	interface BookingInfo {
28	  id: number;
29	  courtId: number;
30	  courtName?: string;
31	  date: string;
32	  startTime: string;
33	  endTime: string;
34	  totalPrice: number;
35	  customerName: string;
36	  customerEmail?: string;
37	  status: string;
38	}
39	
40	interface SplitConfirmInfo {
41	  bookingId: number;
42	  gameId: number | null;
43	  shareToken: string | null;
44	  pricePerSlot: number;
45	  totalSlots: number;
46	  paidSlots: number;
47	  totalPrice: number;
48	  date: string;
49	  startTime: string;
50	  endTime: string;
51	  sport: string | null;
52	  isPublic: boolean;
53	  courtId: number | null;
54	  courtName: string | null;
55	  courtImageUrl: string | null;
56	}
57	
58	function formatBookingDate(value: string): string {
59	  const date = new Date(value);
60	  return Number.isNaN(date.getTime()) ? value : format(date, "yyyy-MM-dd");
61	}
62	
63	interface CalendarInfo {
64	  bookingId: number;
65	  date: string;
66	  startTime: string;
67	  endTime: string;
68	  courtName: string | null;
69	}
70	
71	function AddToCalendarButton({ info }: { info: CalendarInfo }) {
72	  const dateStr = info.date.split("T")[0].replace(/-/g, "");
73	  const start = `${dateStr}T${info.startTime.slice(0, 5).replace(":", "")}00`;
74	  const end = `${dateStr}T${info.endTime.slice(0, 5).replace(":", "")}00`;
75	  const courtLabel = info.courtName ?? "Kortas";
76	  const title = `Rezervacija – ${courtLabel}`;
77	  const details = [
78	    `📅 Rezervacija #${info.bookingId}`,
79	    `🏟 Aikštelė: ${courtLabel}`,
80	    `🔗 Peržiūrėti: ${window.location.origin}${BASE}/bookings/${info.bookingId}`,
81	  ].join("\n");
82	  const googleUrl =
83	    `https://calendar.google.com/calendar/render?action=TEMPLATE` +
84	    `&text=${encodeURIComponent(title)}` +
85	    `&dates=${start}/${end}` +
86	    `&ctz=Europe%2FVilnius` +
87	    `&details=${encodeURIComponent(details)}`;
88	
89	  return (
90	    <DropdownMenu>
91	      <DropdownMenuTrigger asChild>
92	        <Button variant="outline" className="w-full gap-2">
93	          <Calendar className="w-4 h-4" />
94	          Pridėti į kalendorių
95	          <ChevronDown className="w-4 h-4 ml-auto" />
96	        </Button>
97	      </DropdownMenuTrigger>
98	      <DropdownMenuContent align="end" className="w-52">
99	        <DropdownMenuItem onClick={() => window.open(googleUrl, "_blank")}>
100	          <img
101	            src="https://ssl.gstatic.com/calendar/images/dynamiclogo_2020q4/calendar_31_2x.png"
102	            className="w-4 h-4 mr-2 object-contain"
103	            alt=""
104	          />
105	          Google Calendar
106	        </DropdownMenuItem>
107	        <DropdownMenuItem onClick={() => window.open(`${API}/bookings/${info.bookingId}/ics`, "_blank")}>
108	          <Download className="w-4 h-4 mr-2" />
109	          Apple Calendar (.ics)
110	        </DropdownMenuItem>
111	      </DropdownMenuContent>
112	    </DropdownMenu>
113	  );
114	}
115	
116	function ShareArea({ url, title }: { url: string; title: string }) {
117	  const [copied, setCopied] = useState(false);
118	
119	  const handleCopy = () => {
120	    navigator.clipboard.writeText(url).then(() => {
121	      setCopied(true);
122	      setTimeout(() => setCopied(false), 2000);
123	    });
124	  };
125	
126	  const handleNativeShare = async () => {
127	    try {
128	      await navigator.share({ title, url });
129	    } catch {
130	      // user cancelled or API not supported
131	    }
132	  };
133	
134	  const hasNativeShare = typeof navigator !== "undefined" && "share" in navigator;
135	
136	  return (
137	    <div className="text-left space-y-2">
138	      <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Dalintis</p>
139	      <div className="flex items-center gap-2 bg-muted/50 rounded-lg px-3 py-2 border border-border">
140	        <p className="text-xs text-muted-foreground truncate flex-1">{url}</p>
141	        <button
142	          onClick={handleCopy}
143	          className="flex items-center gap-1 text-xs text-primary hover:text-primary/80 transition-colors shrink-0"
144	        >
145	          {copied ? <Check className="w-3.5 h-3.5" /> : <Copy className="w-3.5 h-3.5" />}
146	          {copied ? "Nukopijuota!" : "Kopijuoti"}
147	        </button>
148	      </div>
149	      {hasNativeShare && (
150	        <Button size="sm" variant="outline" className="gap-1.5" onClick={handleNativeShare}>
151	          <Share2 className="w-3.5 h-3.5" />
152	          Dalintis
153	        </Button>
154	      )}
155	    </div>
156	  );
157	}
158	
159	const signUpAppearance: React.ComponentProps<typeof SignUp>["appearance"] = {
160	  variables: {
161	    colorPrimary: "#84cc16",
162	    colorBackground: "transparent",
163	    colorText: "var(--foreground)",
164	    colorInputBackground: "var(--muted)",
165	    colorInputText: "var(--foreground)",
166	    borderRadius: "0.75rem",
167	    fontFamily: "inherit",
168	    fontSize: "0.875rem",
169	  },
170	  elements: {
171	    rootBox: "w-full",
172	    card: "shadow-none border-0 p-0 bg-transparent w-full",
173	    header: "hidden",
174	    headerTitle: "hidden",
175	    headerSubtitle: "hidden",
176	    socialButtonsBlockButton:
177	      "border border-border bg-muted hover:bg-muted/70 text-foreground rounded-xl h-10 font-medium transition-colors",
178	    dividerLine: "bg-border",
179	    dividerText: "text-muted-foreground text-xs",
180	    formFieldLabel: "text-sm font-medium text-foreground text-left block",
181	    formFieldInput:
182	      "bg-muted border border-border rounded-xl h-10 text-foreground placeholder:text-muted-foreground focus:border-lime-500",
183	    formButtonPrimary:
184	      "bg-lime-500 hover:bg-lime-600 text-black font-semibold rounded-xl h-10 transition-colors",
185	    footer: { display: "none" },
186	    footerAction: { display: "none" },
187	    formFieldSuccessText: "text-lime-600",
188	    formFieldErrorText: "text-destructive text-xs",
189	    alertText: "text-sm",
190	  },
191	};
192	
193	function ClaimProfileSection({ email }: { email: string }) {
194	  const [expanded, setExpanded] = useState(false);
195	
196	  return (
197	    <div className="border border-primary/30 rounded-xl bg-primary/5 text-left overflow-hidden">
198	      <button
199	        type="button"
200	        onClick={() => setExpanded(v => !v)}
201	        className="w-full flex items-center gap-3 px-4 py-3.5 hover:bg-primary/10 transition-colors"
202	      >
203	        <div className="w-8 h-8 rounded-full bg-primary/20 flex items-center justify-center shrink-0">
204	          <UserPlus className="w-4 h-4 text-primary" />
205	        </div>
206	        <div className="flex-1 min-w-0 text-left">
207	          <p className="text-sm font-semibold text-foreground">Sukurkite paskyrą</p>
208	          <p className="text-xs text-muted-foreground truncate">
209	            Sutaupykite laiką kitą kartą – duomenys bus užpildyti automatiškai
210	          </p>
211	        </div>
212	        <span className="text-xs font-medium text-primary shrink-0">
213	          {expanded ? "Uždaryti" : "Registruotis"}
214	        </span>
215	      </button>
216	
217	      {expanded && (
218	        <div className="px-4 pb-5 pt-1 border-t border-primary/20">
219	          <p className="text-xs text-muted-foreground mb-4 leading-relaxed">
220	            Mokėjimas sėkmingas! Sukurkite paskyrą, kad nereikėtų vesti duomenų kitą kartą
221	            ir galėtumėte sekti visas savo rezervacijas vienoje vietoje.
222	          </p>
223	          <SignUp
224	            routing="hash"
225	            fallbackRedirectUrl={`${BASE}/bookings`}
226	            initialValues={{ emailAddress: email }}
227	            appearance={signUpAppearance}
228	          />
229	        </div>
230	      )}
231	    </div>
232	  );
233	}
234	
235	export default function BookingConfirmed() {
236	  const [, setLocation] = useLocation();
237	  const queryClient = useQueryClient();
238	  const { isLoaded: authLoaded, isSignedIn } = useSafeAuth();
239	  const params = new URLSearchParams(window.location.search);
240	  const bookingId = params.get("id");
241	  const sessionId = params.get("session_id");
242	  const isSplit = params.get("split") === "1";
243	
244	  const [booking, setBooking] = useState<BookingInfo | null>(null);
245	  const [splitInfo, setSplitInfo] = useState<SplitConfirmInfo | null>(null);
246	  const [state, setState] = useState<"loading" | "success" | "error">("loading");
247	  const [reservedAt, setReservedAt] = useState<Date | null>(null);
248	  const [courtOwner, setCourtOwner] = useState<{ userId: string; name: string } | null>(null);
249	
250	  useEffect(() => {
251	    try { sessionStorage.removeItem("stripeCancel_pending"); } catch { /* ignore */ }
252	    const confirm = async () => {
253	      try {
254	        if (isSplit && sessionId) {
255	          const r = await fetch(`${API}/payments/confirm-split`, {
256	            method: "POST",
257	            headers: { "Content-Type": "application/json" },
258	            body: JSON.stringify({ sessionId }),
259	          });
260	          if (!r.ok) throw new Error("Split payment confirmation failed");
261	          const data: SplitConfirmInfo = await r.json();
262	          setSplitInfo(data);
263	        } else if (sessionId && !sessionId.startsWith("mock_")) {
264	          const r = await fetch(`${API}/payments/confirm`, {
265	            method: "POST",
266	            headers: { "Content-Type": "application/json" },
267	            body: JSON.stringify({ sessionId }),
268	          });
269	          if (!r.ok) throw new Error("Payment confirmation failed");
270	          const data = await r.json();
271	          setBooking(data);
272	        } else if (bookingId) {
273	          const r = await fetch(`${API}/bookings/${bookingId}`);
274	          if (r.ok) {
275	            const data = await r.json();
276	            setBooking({ ...data, totalPrice: Number(data.totalPrice ?? 0) });
277	          }
278	        }
279	        await Promise.all([
280	          queryClient.invalidateQueries({ queryKey: ["/api/bookings"] }),
281	          queryClient.invalidateQueries({ queryKey: ["court-activity"] }),
282	          queryClient.invalidateQueries({ queryKey: ["open-matches"] }),
283	          queryClient.invalidateQueries({ predicate: (q) => {
284	            const k = q.queryKey?.[0];
285	            return typeof k === "string" && k.includes("/availability");
286	          } }),
287	        ]);
288	        setReservedAt(new Date());
289	        setState("success");
290	      } catch {
291	        setState("error");
292	      }
293	    };
294	    confirm();
295	  }, []);
296	
297	  // Fetch court owner info once courtId is known (for "Chat with court" button)
298	  useEffect(() => {
299	    const cid = splitInfo?.courtId ?? booking?.courtId;
300	    if (!cid) return;
301	    fetch(`${API}/courts/${cid}`)
302	      .then(r => r.ok ? r.json() : null)
303	      .then((c: any) => {
304	        if (c?.ownerUserId) setCourtOwner({ userId: c.ownerUserId, name: c.ownerName || "Savininkas" });
305	      })
306	      .catch(() => {});
307	  }, [splitInfo?.courtId, booking?.courtId]);
308	
309	  const shareUrl = splitInfo?.shareToken
310	    ? `${window.location.origin}${BASE}/join/${splitInfo.shareToken}`
311	    : null;
312	
313	  const courtPageUrl = splitInfo?.courtId
314	    ? `${BASE}/courts/${splitInfo.courtId}`
315	    : booking?.courtId
316	      ? `${BASE}/courts/${booking.courtId}`
317	      : null;
318	
319	  return (
320	    <Layout>
321	      <div className="container mx-auto flex items-center justify-center min-h-[70vh] px-4 py-8">
322	        <div className="max-w-md w-full bg-card border rounded-2xl p-8 text-center shadow-xl space-y-6">
323	
324	          {state === "loading" && (
325	            <>
326	              <div className="flex items-center justify-center">
327	                <div className="w-20 h-20 rounded-full bg-primary/10 flex items-center justify-center">
328	                  <Loader2 className="w-12 h-12 text-primary animate-spin" />
329	                </div>
330	              </div>
331	              <div>
332	                <h1 className="text-2xl font-bold mb-2">Apdorojamas mokėjimas…</h1>
333	                <p className="text-muted-foreground text-sm">Prašome palaukti</p>
334	              </div>
335	            </>
336	          )}
337	
338	          {state === "error" && (
339	            <>
340	              <div className="flex items-center justify-center">
341	                <div className="w-20 h-20 rounded-full bg-destructive/10 flex items-center justify-center">
342	                  <XCircle className="w-12 h-12 text-destructive" />
343	                </div>
344	              </div>
345	              <div>
346	                <h1 className="text-2xl font-bold mb-2">Mokėjimas nepavyko</h1>
347	                <p className="text-muted-foreground text-sm">Bandykite dar kartą arba susisiekite su mumis.</p>
348	              </div>
349	              <Button onClick={() => setLocation("/courts")} className="w-full">
350	                Grįžti į aikštelių sąrašą
351	              </Button>
352	            </>
353	          )}
354	
355	          {state === "success" && splitInfo && (
356	            <>
357	              <div className="flex items-center justify-center">
358	                <div className="w-20 h-20 rounded-full bg-primary/10 flex items-center justify-center">
359	                  <CheckCircle2 className="w-12 h-12 text-primary" />
360	                </div>
361	              </div>
362	
363	              <div>
364	                <h1 className="text-2xl font-bold mb-2">Žaidimas sukurtas!</h1>
365	                <p className="text-muted-foreground text-sm leading-relaxed">
366	                  Sumokėjote savo dalį (€{splitInfo.pricePerSlot.toFixed(2)}). Pakviesk žaidėjus ir padalinkite kortą.
367	                </p>
368	              </div>
369	
370	              {/* Court info (clickable) */}
371	              {splitInfo.courtName && (
372	                <button
373	                  type="button"
374	                  onClick={() => courtPageUrl && setLocation(courtPageUrl)}
375	                  className="w-full text-left bg-muted/40 hover:bg-muted/70 border border-border hover:border-primary/40 rounded-xl overflow-hidden transition-all group"
376	                >
377	                  {splitInfo.courtImageUrl && (
378	                    <div className="h-24 overflow-hidden">
379	                      <img
380	                        src={splitInfo.courtImageUrl.startsWith("http") ? splitInfo.courtImageUrl : `${BASE}/${splitInfo.courtImageUrl}`}
381	                        alt={splitInfo.courtName}
382	                        className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
383	                      />
384	                    </div>
385	                  )}
386	                  <div className="px-4 py-3 flex items-center justify-between">
387	                    <div className="flex items-center gap-2">
388	                      <span className="text-lg">🏟️</span>
389	                      <span className="font-semibold text-sm group-hover:text-primary transition-colors">{splitInfo.courtName}</span>
390	                    </div>
391	                    <ExternalLink className="w-3.5 h-3.5 text-muted-foreground group-hover:text-primary transition-colors" />
392	                  </div>
393	                </button>
394	              )}
395	
396	              {/* Date / time summary */}
397	              <div className="bg-muted/40 rounded-xl p-4 flex flex-col gap-2.5 text-sm text-left">
398	                <div className="flex items-center gap-2 text-muted-foreground">
399	                  <Calendar className="w-4 h-4 shrink-0" />
400	                  <span>{formatBookingDate(splitInfo.date)}</span>
401	                </div>
402	                <div className="flex items-center gap-2 text-muted-foreground">
403	                  <Clock className="w-4 h-4 shrink-0" />
404	                  <span>{splitInfo.startTime} – {splitInfo.endTime}</span>
405	                </div>
406	                {reservedAt && (
407	                  <div className="flex items-center gap-2 text-muted-foreground border-t border-border pt-2 mt-0.5">
408	                    <Check className="w-4 h-4 shrink-0 text-primary" />
409	                    <span>Rezervuota {format(reservedAt, "yyyy-MM-dd HH:mm")}</span>
410	                  </div>
411	                )}
412	              </div>
413	
414	              {/* Pricing breakdown */}
415	              <div className="bg-muted/30 rounded-xl p-4 text-left space-y-2">
416	                <div className="flex items-center justify-between text-sm">
417	                  <span className="flex items-center gap-1.5 text-muted-foreground">
418	                    <CreditCard className="w-4 h-4" />
419	                    Jūsų dalis (1/{splitInfo.totalSlots})
420	                  </span>
421	                  <span className="font-bold text-primary text-base">€{splitInfo.pricePerSlot.toFixed(2)}</span>
422	                </div>
423	                <div className="flex items-center justify-between text-sm border-t border-border pt-2">
424	                  <span className="text-muted-foreground">Visa rezervacijos kaina</span>
425	                  <span className="font-semibold">€{splitInfo.totalPrice.toFixed(2)}</span>
426	                </div>
427	                <div className="flex items-center justify-between text-sm">
428	                  <span className="text-muted-foreground">Liko surinkti iš kitų</span>
429	                  <span className="font-semibold text-orange-500 dark:text-orange-400">
430	                    €{Math.max(0, splitInfo.totalPrice - splitInfo.pricePerSlot).toFixed(2)}
431	                  </span>
432	                </div>
433	              </div>
434	
435	              {/* Player slots progress */}
436	              <div className="bg-muted/30 rounded-xl p-4 text-left space-y-3">
437	                <div className="flex items-center justify-between text-sm">
438	                  <span className="flex items-center gap-1.5 font-medium">
439	                    <Users className="w-4 h-4 text-primary" />
440	                    Žaidėjai
441	                  </span>
442	                  <span className="font-bold">{splitInfo.paidSlots}/{splitInfo.totalSlots} apmokėjo</span>
443	                </div>
444	                <div className="w-full bg-muted rounded-full h-2 overflow-hidden">
445	                  <div
446	                    className="h-2 rounded-full bg-primary transition-all"
447	                    style={{ width: `${Math.round((splitInfo.paidSlots / splitInfo.totalSlots) * 100)}%` }}
448	                  />
449	                </div>
450	                <div className="flex gap-1.5">
451	                  {Array.from({ length: splitInfo.totalSlots }).map((_, i) => (
452	                    <div
453	                      key={i}
454	                      className={`flex-1 h-7 rounded-md border flex items-center justify-center text-[10px] font-bold transition-colors ${
455	                        i < splitInfo.paidSlots
456	                          ? "bg-primary border-primary text-primary-foreground"
457	                          : "bg-muted/60 border-border text-muted-foreground"
458	                      }`}
459	                    >
460	                      {i < splitInfo.paidSlots ? "✓" : `${(splitInfo.pricePerSlot).toFixed(0)}€`}
461	                    </div>
462	                  ))}
463	                </div>
464	                <p className="text-xs text-muted-foreground">
465	                  Kiekvienas žaidėjas moka <span className="font-semibold text-foreground">€{splitInfo.pricePerSlot.toFixed(2)}</span>
466	                </p>
467	              </div>
468	
469	              {/* Share link */}
470	              {shareUrl && (
471	                <div className="text-left space-y-1">
472	                  <ShareArea
473	                    url={shareUrl}
474	                    title={`Prisijunk prie žaidimo aikštelėje ${splitInfo.courtName ?? "korts.lt"}!`}
475	                  />
476	                  <p className="text-xs text-muted-foreground pt-1">
477	                    Žaidėjai, paspaudę nuorodą, galės prisijungti ir sumokėti savo dalį.
478	                  </p>
479	                </div>
480	              )}
481	
482	              {isSignedIn && courtOwner && (
483	                <Button
484	                  variant="outline"
485	                  className="w-full gap-2"
486	                  onClick={() => openChat({
487	                    userId: courtOwner.userId,
488	                    userName: courtOwner.name,
489	                    ctxType: "booking",
490	                    ctxId: splitInfo.bookingId,
491	                  })}
492	                >
493	                  <MessageCircle className="w-4 h-4" />
494	                  Rašyti kortui
495	                </Button>
496	              )}
497	
498	              <AddToCalendarButton
499	                info={{
500	                  bookingId: splitInfo.bookingId,
501	                  date: splitInfo.date,
502	                  startTime: splitInfo.startTime,
503	                  endTime: splitInfo.endTime,
504	                  courtName: splitInfo.courtName,
505	                }}
506	              />
507	
508	              {sessionId?.startsWith("mock_") && (
509	                <div className="bg-yellow-500/10 border border-yellow-500/20 rounded-xl p-3 text-xs text-yellow-600 dark:text-yellow-400 text-left">
510	                  🔑 <strong>Sandbox režimas:</strong> Naudotas testavimo mokėjimas. Realūs pinigai nenurašyti.
511	                </div>
512	              )}
513	
514	              <div className="flex gap-3">
515	                {splitInfo.isPublic && (
516	                  <Button variant="outline" className="flex-1" onClick={() => setLocation("/matches")}>
517	                    <Globe className="w-4 h-4 mr-1" />
518	                    Atviri mačai
519	                  </Button>
520	                )}
521	                <Button onClick={() => setLocation("/bookings")} className="flex-1 gap-2">
522	                  Mano rezervacijos
523	                  <ArrowRight className="w-4 h-4" />
524	                </Button>
525	              </div>
526	            </>
527	          )}
528	
529	          {state === "success" && !splitInfo && (
530	            <>
531	              <div className="flex items-center justify-center">
532	                <div className="w-20 h-20 rounded-full bg-primary/10 flex items-center justify-center">
533	                  <CheckCircle2 className="w-12 h-12 text-primary" />
534	                </div>
535	              </div>
536	
537	              <div>
538	                <h1 className="text-2xl font-bold mb-2">Rezervacija patvirtinta!</h1>
539	                <p className="text-muted-foreground text-sm leading-relaxed">
