322	                    key={i}
323	                    className={`w-8 h-8 rounded-lg border-2 flex items-center justify-center text-xs font-bold ${
324	                      isPaid
325	                        ? "bg-blue-500 border-blue-500 text-white"
326	                        : "bg-muted border-border text-muted-foreground"
327	                    }`}
328	                  >
329	                    {isPaid ? "✓" : i + 1}
330	                  </div>
331	                );
332	              })}
333	            </div>
334	
335	            <Separator />
336	
337	            {/* Participant list */}
338	            {splitStatus.participants.length > 0 && (
339	              <div className="px-4 py-3 space-y-2">
340	                <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-2">Žaidėjai</p>
341	                {splitStatus.participants.map((p, i) => (
342	                  <div key={i} className="flex items-center justify-between gap-2 text-sm">
