179	              <p className="text-xs opacity-80">Tavo dalis sėkmingai apmokėta.</p>
180	            </div>
181	          </div>
182	        )}
183	
184	        {/* Cancelled banner */}
185	        {isCancelled && (
186	          <div className="flex items-center gap-3 p-4 rounded-xl bg-yellow-500/10 border border-yellow-400/20 text-yellow-700 dark:text-yellow-400">
