407	
408	router.post("/payments/confirm-split", requireAuth, async (req, res): Promise<void> => {
409	  const userId = getCurrentUserId(req)!;
410	  const sessionId = String(req.body?.sessionId ?? "");
411	  if (!sessionId) { res.status(400).json({ error: "sessionId required" }); return; }
412	
413	  // Find the booking (and court) by stripeSessionId
414	  const rows = await db
415	    .select({ booking: bookingsTable, court: courtsTable })
416	    .from(bookingsTable)
417	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
418	    .where(eq(bookingsTable.stripeSessionId, sessionId));
419	
420	  if (!rows[0]) { res.status(404).json({ error: "Booking not found for session" }); return; }
421	  const { booking, court } = rows[0];
422	  if (!booking.isSplit) { res.status(400).json({ error: "Not a split booking" }); return; }
423	  if (booking.bookerUserId !== userId) { res.status(403).json({ error: "Forbidden" }); return; }
424	
425	  // Verify Stripe payment and read metadata (skip for mocks)
426	  let linkGameId: number | null = null;
427	  let hostStripeCustomerId: string | null = null;
428	  let hostStripePaymentMethodId: string | null = null;
429	  if (!sessionId.startsWith("mock_")) {
430	    try {
431	      const stripe = await getUncachableStripeClient();
432	      const session = await stripe.checkout.sessions.retrieve(sessionId, {
433	        expand: ["payment_intent"],
434	      });
435	      if (session.payment_status !== "paid") {
436	        res.status(402).json({ error: "Payment not completed" });
437	        return;
438	      }
439	      const lgId = session.metadata?.linkGameId;
440	      if (lgId) linkGameId = parseInt(lgId, 10);
441	      // Persist host's Stripe customer + saved payment method for guarantee charges
442	      if (session.customer) hostStripeCustomerId = session.customer as string;
443	      const pi = session.payment_intent as any;
444	      if (pi?.payment_method) hostStripePaymentMethodId = pi.payment_method as string;
445	    } catch (err) {
446	      logger.error({ err }, "Stripe retrieve session error in confirm-split");
447	    }
448	  }
449	
450	  // Find participant by stripeSessionId → mark as paid (idempotent)
451	  const [participant] = await db
452	    .select()
453	    .from(gameParticipantsTable)
454	    .where(eq(gameParticipantsTable.stripeSessionId, sessionId));
455	
456	  if (participant && participant.paymentStatus !== "paid") {
457	    await db
458	      .update(gameParticipantsTable)
459	      .set({ paymentStatus: "paid" })
460	      .where(eq(gameParticipantsTable.id, participant.id));
461	  }
462	
463	  // Move booking to awaiting_players (from pending) — track if this is a fresh transition
464	  let justTransitioned = false;
465	  if (booking.status === "pending") {
466	    const updated = await db
467	      .update(bookingsTable)
468	      .set({
469	        status: "awaiting_players",
470	        ...(hostStripeCustomerId ? { hostStripeCustomerId } : {}),
471	        ...(hostStripePaymentMethodId ? { hostStripePaymentMethodId } : {}),
472	      })
473	      .where(and(eq(bookingsTable.id, booking.id), eq(bookingsTable.status, "pending")))
474	      .returning();
475	    justTransitioned = updated.length > 0;
476	  }
477	
478	  // Find linked game and transition it
479	  let game: typeof gamesTable.$inferSelect | undefined;
480	  if (linkGameId) {
481	    // Upgrade flow: update the pre-existing casual game
482	    const [courtRow] = await db
483	      .select({ facilityId: facilitiesTable.id, courtId: courtsTable.id })
484	      .from(courtsTable)
485	      .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
486	      .where(eq(courtsTable.id, booking.courtId));
487	    await db
488	      .update(gamesTable)
489	      .set({
490	        bookingId: booking.id,
491	        facilityId: courtRow?.facilityId ?? null,
492	        courtId: courtRow?.courtId ?? booking.courtId,
493	        status: "awaiting_players",
494	        datetime: `${booking.date}T${booking.startTime}:00`,
495	        durationMinutes: toMin(booking.endTime) - toMin(booking.startTime),
496	      })
497	      .where(eq(gamesTable.id, linkGameId));
498	    const [updated] = await db.select().from(gamesTable).where(eq(gamesTable.id, linkGameId));
499	    game = updated;
500	  } else {
501	    // Normal flow: find the game that was created alongside this booking
502	    const [found] = await db
503	      .select()
504	      .from(gamesTable)
505	      .where(eq(gamesTable.bookingId, booking.id));
506	    if (found && found.status === "pending_payment") {
507	      await db
508	        .update(gamesTable)
509	        .set({ status: "awaiting_players" })
510	        .where(and(eq(gamesTable.id, found.id), eq(gamesTable.status, "pending_payment")));
511	    }
512	    game = found;
513	  }
514	
515	  // Aggregate paid participant count
516	  const allParticipants = game
517	    ? await db
518	        .select({ paymentStatus: gameParticipantsTable.paymentStatus })
519	        .from(gameParticipantsTable)
520	        .where(and(
521	          eq(gameParticipantsTable.gameId, game.id),
522	          eq(gameParticipantsTable.status, "joined"),
523	        ))
524	    : [];
525	  const paidSlots = allParticipants.filter(p => p.paymentStatus === "paid").length;
526	
527	  // Send email + notification to host if this was a fresh game creation
528	  if (justTransitioned && booking.bookerUserId && booking.splitInviteToken) {
529	    const origin = req.get("origin") ?? req.get("host") ?? "https://korts.lt";
530	    const base = process.env.BASE_PATH ?? "";
531	    const shareLink = `${origin}${base}/join/${booking.splitInviteToken}`;
532	
533	    sendSplitBookingCreatedEmail({
534	      hostName: booking.customerName,
535	      hostEmail: booking.customerEmail,
536	      courtName: court?.name ?? "Kortas",
537	      courtId: booking.courtId,
538	      date: booking.date,
539	      startTime: booking.startTime,
540	      endTime: booking.endTime,
541	      pricePerSlot: Number(booking.pricePerSlot ?? 0),
542	      totalPrice: Number(booking.totalPrice),
543	      totalSlots: booking.totalSlots ?? 1,
544	      shareLink,
545	      bookingId: booking.id,
546	    }).catch((err) => logger.error({ err }, "sendSplitBookingCreatedEmail failed"));
547	
548	    sendNotification(
549	      booking.bookerUserId,
550	      "split_player_joined",
551	      "Žaidimas sukurtas!",
552	      `Jūsų vieta aikštelėje ${court?.name ?? "kortas"} (${booking.date}) patvirtinta. Dalinkitės nuoroda su žaidėjais.`,
553	      `/bookings/${booking.id}`,
554	    ).catch(() => {});
555	  }
556	
557	  res.json({
558	    bookingId: booking.id,
559	    gameId: game?.id ?? null,
560	    shareToken: booking.splitInviteToken ?? null,
561	    pricePerSlot: Number(booking.pricePerSlot ?? 0),
562	    totalSlots: booking.totalSlots ?? 1,
563	    paidSlots,
564	    totalPrice: Number(booking.totalPrice),
565	    date: booking.date,
566	    startTime: booking.startTime,
567	    endTime: booking.endTime,
568	    sport: game?.sport ?? null,
569	    isPublic: game?.visibility === "public",
570	    courtId: booking.courtId,
571	    courtName: court?.name ?? null,
572	    courtImageUrl: court?.imageUrl ?? null,
573	  });
574	});
