589	  if (!rows[0]) { res.status(404).json({ error: "Invite link not found" }); return; }
590	
591	  const { booking, court, facility } = rows[0];
592	
593	  if (!booking.isSplit) { res.status(400).json({ error: "Not a split booking" }); return; }
594	
595	  if (booking.status === "cancelled") {
596	    res.status(410).json({ error: "Booking was cancelled" });
597	    return;
598	  }
599	
600	  // Get linked game + participant counts
601	  const [game] = await db.select().from(gamesTable).where(eq(gamesTable.bookingId, booking.id));
602	
603	  let paidCount = 0;
604	  let pendingCount = 0;
605	  let paidParticipantNames: string[] = [];
