85	function formatDate(value: string): string {
86	  const d = new Date(value);
87	  return Number.isNaN(d.getTime()) ? value : format(d, "yyyy-MM-dd");
88	}
89	
90	function formatDateLong(value: string): string {
91	  const d = new Date(value);
92	  return Number.isNaN(d.getTime()) ? value : format(d, "EEEE, yyyy-MM-dd", { locale: lt });
93	}
