116	function StatusBadge({ status }: { status: string }) {
117	  switch (status) {
118	    case "confirmed":
119	      return <Badge className="bg-green-500 text-white"><CheckCircle2 className="w-3 h-3 mr-1" />Patvirtinta</Badge>;
120	    case "pending":
121	      return <Badge variant="secondary" className="bg-yellow-500/20 text-yellow-700 dark:text-yellow-400"><Clock className="w-3 h-3 mr-1" />Laukiama</Badge>;
122	    case "awaiting_players":
123	      return <Badge variant="secondary" className="bg-blue-500/20 text-blue-700 dark:text-blue-400"><Users className="w-3 h-3 mr-1" />Laukiama žaidėjų</Badge>;
124	    case "cancelled":
125	      return <Badge variant="destructive"><XCircle className="w-3 h-3 mr-1" />Atšaukta</Badge>;
126	    default:
127	      return <Badge variant="outline">{status}</Badge>;
128	  }
129	}
