    const [eh, em] = booking.endTime.split(":").map(Number);
    const mins = (eh * 60 + em) - (sh * 60 + (sm ?? 0));
    const h = Math.floor(mins / 60);
    const m = mins % 60;
    return m > 0 ? `${h}h ${m}min` : `${h}h`;
  })();

  return (
    <Layout>
      <div className="container mx-auto px-4 py-8 max-w-lg">
        {/* Back button */}
        <BackButton to="/bookings" label="Visos rezervacijos" />

        {/* Header */}
        <div className="flex items-start justify-between gap-3 mb-6">
          <div>
            <h1 className="text-xl font-bold">Rezervacija #{booking.id}</h1>
            <p className="text-sm text-muted-foreground mt-0.5">{courtName}</p>
          </div>
          <StatusBadge status={booking.status} />
        </div>

        {/* Booking info card */}
        <div className="bg-card border rounded-xl divide-y divide-border overflow-hidden mb-4">
          <div className="w-full px-4 py-3 flex items-center gap-3">
            {resolveCourtImage(court?.imageUrl, court?.type) ? (
              <img
                src={resolveCourtImage(court?.imageUrl, court?.type)!}
                alt={courtName}
                className="w-10 h-10 rounded-lg object-cover shrink-0"
              />
            ) : (
              <Building2 className="w-4 h-4 text-muted-foreground shrink-0" />
            )}
            <button
              className="flex-1 flex flex-col min-w-0 text-left"
              onClick={() => setLocation(`/courts/${booking.courtId}`)}
            >
              <p className="text-xs text-muted-foreground">Aikštelė</p>
              <p className="text-sm font-medium text-primary truncate">{courtName}</p>
            </button>
            <ExternalLink
              className="w-3.5 h-3.5 text-muted-foreground shrink-0 cursor-pointer hover:text-primary transition-colors"
              onClick={() => setLocation(`/courts/${booking.courtId}`)}
            />
            {isSignedIn && court?.ownerUserId && (
              <button
