const [guestName, setGuestName] = useState("");
const [guestEmail, setGuestEmail] = useState("");

const params = new URLSearchParams(typeof window !== "undefined" ? window.location.search : "");
const isPaid = params.get("paid") === "1";
const isCancelled = params.get("cancelled") === "1";

useEffect(() => {
  if (!token) { setError("Nuoroda neteisinga"); setLoading(false); return; }
  fetch(`${API}/bookings/share/${token}`)
    .then(r => {
      if (r.status === 404) throw new Error("Kvietimo nuoroda nerasta arba nebegalioja.");
      if (r.status === 410) throw new Error("Rezervacija atšaukta.");
      if (!r.ok) throw new Error("Nepavyko gauti rezervacijos informacijos.");
      return r.json();
    })
    .then(async (data: SplitBookingInfo) => {
      setInfo(data);
      if (data.courtId) {
        const courtRes = await fetch(`${API}/courts/${data.courtId}`).catch(() => null);
        if (courtRes?.ok) {
          const c = await courtRes.json();
          setCourtAddress({ address: c.address ?? null, city: c.city ?? null });
        }
      }
    })
    .catch(err => setError(err.message))
    .finally(() => setLoading(false));
}, [token]);

