import { db, notificationsTable, notificationSettingsTable } from "@workspace/db";
import { eq } from "drizzle-orm";

export const ADMIN_NOTIF_USER = "__ADMIN__";

type NotifType =
  | "game_join_request"
  | "game_cancelled"
  | "booking_created"
  | "booking_cancelled"
  | "court_approved"
  | "court_rejected"
  | "facility_approved"
  | "facility_rejected"
  | "coach_approved"
  | "coach_rejected"
  | "court_coach_approved"
  | "court_coach_rejected"
  | "coach_invite"
  | "coach_application"
  | "tournament_pending_review"
  | "tournament_approved"
  | "tournament_rejected"
  | "tournament_match_ready"
  | "admin_pending_review"
  | "game_join_rejected"
  | "game_join_approved"
  | "game_removed"
  | "result_confirmation"
  | "result_disputed"
  | "elo_update"
  | "message"
  | "split_player_joined"
  | "split_guarantee_charged"
  | "split_guarantee_failed"
  | "split_guarantee_refunded";

const TYPE_TO_SETTING: Partial<Record<NotifType, keyof typeof notificationSettingsTable.$inferSelect>> = {
  game_join_request: "gameJoinRequest",
  game_cancelled: "gameCancelled",
  booking_created: "bookingCreated",
  booking_cancelled: "bookingCancelled",
  court_approved: "courtApproved",
  court_rejected: "courtApproved",
  facility_approved: "courtApproved",
  facility_rejected: "courtApproved",
  coach_approved: "courtApproved",
  coach_rejected: "courtApproved",
  message: "messageReceived",
};

async function shouldNotify(userId: string, type: NotifType): Promise<boolean> {
  // Admin pseudo-user always receives notifications
  if (userId === ADMIN_NOTIF_USER) return true;
  try {
    const [row] = await db
      .select()
      .from(notificationSettingsTable)
      .where(eq(notificationSettingsTable.userId, userId));
    if (!row) return true;
    const field = TYPE_TO_SETTING[type];
    if (!field) return true;
    return row[field] as boolean;
  } catch {
    return true;
  }
}

export async function sendNotification(
  userId: string,
  type: NotifType,
  title: string,
  body: string,
  link?: string,
) {
  try {
    const allowed = await shouldNotify(userId, type);
    if (!allowed) return;
    await db.insert(notificationsTable).values({
      userId,
      type,
      title,
      body,
      link: link ?? null,
    });
  } catch { /* silent */ }
}

/** Send a notification to the admin queue (special sentinel user) */
export async function sendAdminNotification(
  title: string,
  body: string,
  link?: string,
) {
  return sendNotification(ADMIN_NOTIF_USER, "admin_pending_review", title, body, link);
}

import type { Request, Response, NextFunction } from "express";
import { getAuth, clerkClient } from "@clerk/express";
import { db } from "@workspace/db";
import { userRolesTable } from "@workspace/db/schema";
import { eq } from "drizzle-orm";
import { timingSafeEqual } from "node:crypto";
import type { UserRole } from "@workspace/db/schema";

/**
 * Test-only auth bypass. If AGENT_BYPASS_KEY is set in env AND a request carries
 * `x-replit-agent-auth: <that key>`, requireAuth/requireOwner/requireCoach/
 * requireAdmin all let the request through. The caller can also provide:
 *   x-replit-agent-userid: <clerk-user-id>   (the userId getCurrentUserId returns)
 *   x-replit-agent-role:   <admin|owner|coach|player>   (the role getUserRole returns)
 * If those headers are omitted, defaults are 'agent-test-user' and 'admin'.
 *
 * The bypass is a no-op when AGENT_BYPASS_KEY is unset, so production safety is
 * preserved as long as that secret is never set in the production environment.
 */
function isAgentBypass(req: Request): boolean {
  const expected = process.env.AGENT_BYPASS_KEY;
  if (!expected) return false;
  const provided = req.header("x-replit-agent-auth");
  if (!provided) return false;
  const a = Buffer.from(expected);
  const b = Buffer.from(provided);
  if (a.length !== b.length) return false;
  return timingSafeEqual(a, b);
}

function bypassUserId(req: Request): string {
  return req.header("x-replit-agent-userid") || "agent-test-user";
}

function bypassRole(req: Request): UserRole {
  const r = req.header("x-replit-agent-role");
  if (r === "admin" || r === "owner" || r === "coach" || r === "player") return r;
  return "admin";
}

/**
 * Inject the bypass userId into Clerk's request-scoped auth so downstream
 * `getAuth(req).userId` calls return the synthetic id rather than null.
 * Safe to call multiple times — it just overwrites req.auth.
 */
function applyBypassToReq(req: Request): void {
  const userId = bypassUserId(req);
  // In @clerk/express v2, getAuth(req) calls `req.auth(options)` and then runs
  // it through getAuthObjectForAcceptedToken which strips userId to null unless
  // tokenType matches the accepted set ("session_token" by default). So we must
  // mimic the shape of signedInAuthObject from @clerk/backend.
  const authState = {
    tokenType: "session_token",
    userId,
    sessionId: "agent-bypass-session",
    sessionStatus: "active",
    sessionClaims: { sub: userId, iss: "agent-bypass", sid: "agent-bypass-session" },
    orgId: null,
    orgRole: null,
    orgSlug: null,
    orgPermissions: null,
    factorVerificationAge: null,
    actor: null,
    isAuthenticated: true,
    has: () => false,
    debug: () => ({}),
    getToken: async () => null,
  };
  // clerkMiddleware sets req.auth via Object.defineProperty, so we must
  // redefine the property to override it.
  Object.defineProperty(req, "auth", {
    configurable: true,
    enumerable: true,
    writable: true,
    value: () => authState,
  });
}

/** IDs in ADMIN_USER_IDS env var always get admin role, even if DB says otherwise */
const HARDCODED_ADMIN_IDS = new Set(
  (process.env.ADMIN_USER_IDS ?? "").split(",").map(s => s.trim()).filter(Boolean)
);

/** Emails in ADMIN_EMAILS env var always get admin role, regardless of Clerk user_id.
 *  Anchored to email (stable) rather than user_id (changes if account is recreated). */
const HARDCODED_ADMIN_EMAILS = new Set(
  (process.env.ADMIN_EMAILS ?? "").split(",").map(s => s.trim().toLowerCase()).filter(Boolean)
);

/** Cache email lookups briefly to avoid hammering Clerk on every request */
const emailCache = new Map<string, { email: string | null; expires: number }>();
const EMAIL_CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes

async function getUserEmail(userId: string): Promise<string | null> {
  const cached = emailCache.get(userId);
  if (cached && cached.expires > Date.now()) return cached.email;
  try {
    const u = await clerkClient.users.getUser(userId);
    const email = u.emailAddresses?.[0]?.emailAddress?.toLowerCase() ?? null;
    emailCache.set(userId, { email, expires: Date.now() + EMAIL_CACHE_TTL_MS });
    return email;
  } catch {
    return null;
  }
}

/** Fetch a user's role from DB; returns 'player' if no row exists.
 *  Users in ADMIN_USER_IDS or whose email is in ADMIN_EMAILS always get 'admin'. */
export async function getUserRole(userId: string): Promise<UserRole> {
  // The agent test bypass uses the synthetic 'agent-test-user' id.
  if (userId === "agent-test-user") return "admin";
  if (HARDCODED_ADMIN_IDS.has(userId)) return "admin";
  if (HARDCODED_ADMIN_EMAILS.size > 0) {
    const email = await getUserEmail(userId);
    if (email && HARDCODED_ADMIN_EMAILS.has(email)) return "admin";
  }
  const [row] = await db
    .select({ role: userRolesTable.role })
    .from(userRolesTable)
    .where(eq(userRolesTable.userId, userId));
  return (row?.role as UserRole) ?? "player";
}

/** Ensure user has a role row (upsert as player on first visit) */
export async function ensureUserRole(userId: string): Promise<UserRole> {
  await db
    .insert(userRolesTable)
    .values({ userId, role: "player" })
    .onConflictDoNothing();
  return getUserRole(userId);
}

/** Express middleware: requires a valid Clerk session */
export function requireAuth(req: Request, res: Response, next: NextFunction): void {
  if (isAgentBypass(req)) { applyBypassToReq(req); next(); return; }
  const { userId } = getAuth(req);
  if (!userId) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }
  next();
}

/** Express middleware: requires role === 'admin' in user_roles table */
export async function requireAdmin(req: Request, res: Response, next: NextFunction): Promise<void> {
  try {
    if (isAgentBypass(req)) {
      if (bypassRole(req) === "admin") { applyBypassToReq(req); next(); return; }
      res.status(403).json({ error: "Forbidden – admin only (bypass role mismatch)" });
      return;
    }
    const { userId } = getAuth(req);
    if (!userId) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }
    const role = await getUserRole(userId);
    if (role !== "admin") {
      res.status(403).json({ error: "Forbidden – admin only" });
      return;
    }
    next();
  } catch (err) {
    next(err);
  }
}

/** Express middleware: requires role === 'admin' or 'owner' */
export async function requireOwner(req: Request, res: Response, next: NextFunction): Promise<void> {
  try {
    if (isAgentBypass(req)) {
      const r = bypassRole(req);
      if (r === "admin" || r === "owner") { applyBypassToReq(req); next(); return; }
      res.status(403).json({ error: "Forbidden – owner or admin only (bypass role mismatch)" });
      return;
    }
    const { userId } = getAuth(req);
    if (!userId) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }
    const role = await getUserRole(userId);
    if (role !== "admin" && role !== "owner") {
      res.status(403).json({ error: "Forbidden – owner or admin only" });
      return;
    }
    next();
  } catch (err) {
    next(err);
  }
}

/** Express middleware: requires role === 'admin' or 'coach' */
export async function requireCoach(req: Request, res: Response, next: NextFunction): Promise<void> {
  try {
    if (isAgentBypass(req)) {
      const r = bypassRole(req);
      if (r === "admin" || r === "coach") { applyBypassToReq(req); next(); return; }
      res.status(403).json({ error: "Forbidden – coach or admin only (bypass role mismatch)" });
      return;
    }
    const { userId } = getAuth(req);
    if (!userId) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }
    const role = await getUserRole(userId);
    if (role !== "admin" && role !== "coach") {
      res.status(403).json({ error: "Forbidden – coach or admin only" });
      return;
    }
    next();
  } catch (err) {
    next(err);
  }
}

/** Express middleware: requires role in {admin, owner, coach} — used for tournament organizers. */
export async function requireCreator(req: Request, res: Response, next: NextFunction): Promise<void> {
  try {
    if (isAgentBypass(req)) {
      const r = bypassRole(req);
      if (r === "admin" || r === "owner" || r === "coach") { applyBypassToReq(req); next(); return; }
      res.status(403).json({ error: "Tik aikštynų savininkai ir treneriai gali organizuoti turnyrus." });
      return;
    }
    const { userId } = getAuth(req);
    if (!userId) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }
    const role = await getUserRole(userId);
    if (role !== "admin" && role !== "owner" && role !== "coach") {
      res.status(403).json({ error: "Tik aikštynų savininkai ir treneriai gali organizuoti turnyrus." });
      return;
    }
    next();
  } catch (err) {
    next(err);
  }
}

/** Returns true if the current request's userId matches the court owner (or is admin) */
export async function isOwner(req: Request, ownerUserId: string | null | undefined): Promise<boolean> {
  if (isAgentBypass(req)) {
    const r = bypassRole(req);
    if (r === "admin") return true;
    if (r === "owner" && ownerUserId && ownerUserId === bypassUserId(req)) return true;
    return false;
  }
  const { userId } = getAuth(req);
  if (!userId) return false;
  if (ownerUserId && ownerUserId === userId) return true;
  // Admins can act as owners
  const role = await getUserRole(userId);
  return role === "admin";
}

export function getCurrentUserId(req: Request): string | null {
  if (isAgentBypass(req)) return bypassUserId(req);
  return getAuth(req).userId ?? null;
}

