        <tr><td style="padding:16px 32px;border-top:1px solid #1f1f1f;">
          <p style="color:#374151;font-size:12px;margin:0;text-align:center;">© ${new Date().getFullYear()} korts.lt</p>
        </td></tr>
      </table>
    </td></tr>
  </table>
</body></html>`.trim();

  try {
    const { error } = await resend.emails.send({
      from: "korts.lt <onboarding@resend.dev>", // TODO: Update to verified production domain
      to: data.playerEmail,
      subject: `Atšauktas mačas ir pinigų grąžinimas: ${data.courtName}`,
      html,
    });
    if (error) console.error("Failed to send split participant refunded email", error);
    else logger.info({ bookingId: data.bookingId, email: data.playerEmail }, "Split participant refunded email sent");
  } catch (err) {
    console.error("Exception sending split participant refunded email", err);
  }
}

