1	import { Router, type IRouter } from "express";
2	import { eq, and, sql, asc, inArray as inArrayDrizzle } from "drizzle-orm";
3	import {
4	  db,
5	  facilitiesTable,
6	  courtsTable,
7	  courtPhotosTable,
8	  userProfilesTable,
9	  bookingsTable,
10	  gamesTable,
11	  reviewsTable,
12	  courtPricingTable,
13	} from "@workspace/db";
14	import { inArray, gte, or } from "drizzle-orm";
15	import { CreateFacilityBody, UpdateFacilityParams, UpdateFacilityBody, DeleteFacilityParams } from "@workspace/api-zod";
16	import { requireAuth, getCurrentUserId, isOwner } from "../lib/auth";
17	import { sendAdminNotification, sendNotification } from "../lib/notify";
18	import {
19	  validateForVerification,
20	  isStripeAccountReady,
21	} from "../lib/facility-status";
22	import { getUncachableStripeClient } from "../stripeClient";
23	import { logger } from "../lib/logger";
24	
25	/**
26	 * Source-of-truth readiness check that calls Stripe directly. Returns one of:
27	 *   - { ready: true }            — Stripe says the account is fully ready
28	 *   - { ready: false }           — Stripe says the account is NOT ready
29	 *   - { ready: false, error: … } — Stripe call failed; caller must NOT promote
30	 *
31	 * Used at the verification gate. Fail-closed by design: when we can't reach
32	 * Stripe, we refuse to advance the facility rather than trusting a possibly
33	 * stale cache. The caller surfaces a 503 so the owner retries later.
34	 */
35	async function ownerStripeReadyLive(
36	  userId: string,
37	): Promise<{ ready: boolean; error?: string }> {
38	  const [profile] = await db
39	    .select()
40	    .from(userProfilesTable)
41	    .where(eq(userProfilesTable.userId, userId));
42	  if (!profile?.stripeAccountId) return { ready: false };
43	
44	  try {
45	    const stripe = await getUncachableStripeClient();
46	    const account = await stripe.accounts.retrieve(profile.stripeAccountId);
47	    return { ready: isStripeAccountReady(account) };
48	  } catch (err: any) {
49	    logger.warn({ err, userId }, "ownerStripeReadyLive: Stripe call failed — failing closed");
50	    return { ready: false, error: err?.message ?? "Stripe unreachable" };
51	  }
52	}
53	
54	const router: IRouter = Router();
55	
56	// Public: minimal facility list for pickers (e.g. coach apply form).
57	// Only fully-active facilities are exposed to avoid leaking unapproved owner data.
58	router.get("/facilities/public", async (_req, res): Promise<void> => {
59	  const rows = await db
60	    .select({
61	      id: facilitiesTable.id,
62	      name: facilitiesTable.name,
63	      city: facilitiesTable.city,
64	      address: facilitiesTable.address,
65	    })
66	    .from(facilitiesTable)
67	    .where(eq(facilitiesTable.verificationStatus, "active"))
68	    .orderBy(facilitiesTable.name);
69	  res.json(rows);
70	});
71	
72	router.get("/facilities", requireAuth, async (req, res): Promise<void> => {
73	  const userId = getCurrentUserId(req);
74	  if (!userId) {
75	    res.status(401).json({ error: "Unauthorized" });
76	    return;
77	  }
78	  const rows = await db.select().from(facilitiesTable).where(eq(facilitiesTable.ownerUserId, userId));
79	
80	  const facilitiesWithCourts = await Promise.all(
81	    rows.map(async (f) => {
82	      const courts = await db
83	        .select({
84	          id: courtsTable.id,
85	          name: courtsTable.name,
86	          type: courtsTable.type,
87	          status: courtsTable.status,
88	          pricePerHour: courtsTable.pricePerHour,
89	          imageUrl: courtsTable.imageUrl,
90	          isIndoor: courtsTable.isIndoor,
91	          rating: courtsTable.rating,
92	        })
93	        .from(courtsTable)
94	        .where(eq(courtsTable.facilityId, f.id));
95	
96	      const sportTypes = [...new Set(courts.map(c => c.type))];
97	
98	      return {
99	        ...f,
100	        description: f.description ?? undefined,
101	        courtCount: courts.length,
102	        sportTypes,
103	        courts,
104	      };
105	    })
106	  );
107	
108	  res.json(facilitiesWithCourts);
109	});
110	
